/**
 * validation_failed (malformed JSON, schema, missing Idempotency-Key, invalid cursor)
 */
export type BadRequestResponse = ErrorResponse;

/**
 * unauthenticated (no valid session token); includes WWW-Authenticate Bearer
 */
export type UnauthenticatedResponse = ErrorResponse;

/**
 * not_linked, account_suspended, account_removed, mfa_required, recent_auth_required or forbidden_role (admin routes also write an audit event)
 */
export type ForbiddenResponse = ErrorResponse;

/**
 * not_found, identical for a missing and a foreign record (BR-22)
 */
export type NotFoundResponse = ErrorResponse;

/**
 * version_conflict, state_conflict or idempotency_key_reused
 */
export type ConflictResponse = ErrorResponse;

/**
 * payload_too_large (states the maximum)
 */
export type PayloadTooLargeResponse = ErrorResponse;

/**
 * unsupported_media_type (states the allowed types)
 */
export type UnsupportedMediaTypeResponse = ErrorResponse;

/**
 * A 422 business-rule refusal; `code` is one of the operation's x-error-codes and `message` states the reason (for example the cap and estimate basis, the used and allowed storage, the clip name)
 */
export type BusinessRuleResponse = ErrorResponse;

/**
 * rate_limited, with Retry-After
 */
export type RateLimitedResponse = ErrorResponse;

/**
 * internal_error; generic message and the request ID only
 */
export type InternalErrorResponse = ErrorResponse;

/**
 * method_not_allowed: the path template exists but does not declare this method. Produced by the router before
 * authentication, for every path, so it is not listed per operation (TD-D34, TD-D37). `Allow` lists the declared
 * methods for the path template, plus `HEAD` when `GET` is declared, never `OPTIONS`, in the order
 * `GET, HEAD, POST, PUT, PATCH, DELETE`, joined by ", ".
 */
export type MethodNotAllowedResponse = ErrorResponse;

/**
 * service_unavailable (database unreachable, a statement or lock timeout, draining, a report data source failed, or no price row effective now for a job-creating call, in which case nothing is created); Retry-After when known
 */
export type ServiceUnavailableResponse = ErrorResponse;

export type LimitParameter = number;

/**
 * Opaque signed token from metaData.pagination.nextCursor. Invalid, tampered, expired or filter-incompatible → 400 validation_failed with detail field `cursor`.
 */
export type CursorParameter = string;

/**
 * Client-generated key (UUID recommended), scoped to the account and the operation, kept IDEMPOTENCY_TTL (24 h). Missing → 400 validation_failed; same key with a different body → 409 idempotency_key_reused; same key and body → the original result.
 */
export type IdempotencyKeyParameter = string;

/**
 * The ETag from the last read ("<version>"). A mismatch → 409 version_conflict with no change (ADR-010 keeps 409 instead of 412).
 */
export type IfMatchParameter = string;

/**
 * Inclusive UTC instant; default now − 30 days
 */
export type ReportFromParameter = string;

/**
 * Exclusive UTC instant; default now; must be after from
 */
export type ReportToParameter = string;

