export type internalMetricsWindowResponse200 = {
  data: MetricsWindowResponse;
  status: 200;
};

export type internalMetricsWindowResponse404 = {
  data: NotFoundResponse;
  status: 404;
};

export type internalMetricsWindowResponse500 = {
  data: InternalErrorResponse;
  status: 500;
};

