export const getInternalMetricsWindowUrl = () => {
  return `/internal/metrics/window`;
};

/**
 * Kept in memory by the api process (one instance; a restart resets it, `processStartedAt` shows when), so a reader
 * needs no stored state. Read by the `monitor` cron every 5 minutes (ALR-2, ALR-3, ALR-7, ALR-9) and by the release
 * observation step every minute (DEVOPS-PLAN §11.4, §14.4). Requests to API-900..903 are not counted. `p95Ms` is null
 * when the window has no request. ALR-9 fires when `telemetryDropped10m` is above 0 (TD-D42); the cumulative
 * `telemetryDroppedTotal` cannot show a rise to a reader without stored state and is not an alert input. Token rule in the scope M convention (TD-D41). Exempt from rate limits; not
 * audit-logged.
 * @summary Windowed request and pool summary of the API process over the last 10 and 15 minutes (internal, metrics token)
 */
export const internalMetricsWindow = async (
  options?: Parameters<typeof httpClient>[1],
): Promise<internalMetricsWindowResponse> => {
  return httpClient<internalMetricsWindowResponse>(getInternalMetricsWindowUrl(), {
    ...options,
    method: 'GET',
  });
};

